"""Markdown reports, generated by code from the JSON reports (the JSON is the source of truth)."""

from __future__ import annotations

from typing import Any


def _esc(s: Any) -> str:
    return str(s).replace("|", "\\|").replace("\n", " ")


def _meta_lines(meta: dict[str, Any]) -> list[str]:
    run, db, cfg = meta["run"], meta["database"], meta["config"]
    docs = meta["docs"] if isinstance(meta["docs"], str) else ", ".join(d["path"] for d in meta["docs"])
    anchor = cfg["time_anchor"]
    return [
        f"- Generated: {run['timestamp_utc']} by `{run['component']}`, model `{run['model']}`, {run['claude_code_version']}",
        f"- Git: {run['git']['commit']}",
        f"- Database: `{db['url']}` ({db['engine']} {db['engine_version']}, {db['tables']} tables, {db['columns']} columns, sha256 `{(db['file_sha256'] or '')[:12]}`)",
        f"- Docs: {docs}",
        f"- Time anchor: {anchor['mode']}" + (f" ({anchor['date']})" if anchor["date"] else ""),
        f"- Input: {', '.join(f'{k}={v}' for k, v in meta['input'].items())}",
    ]


def _links_md(links: list[dict[str, Any]]) -> str:
    parts = []
    for l in links:
        if l["kind"] == "table":
            target = l.get("table")
        elif l["kind"] == "column":
            target = ", ".join(l.get("columns", []))
            if "value" in l:
                target += f" = `{l['value']}`" + (" (contains)" if l.get("match") == "contains" else "")
            if l.get("alternatives"):
                target += " OR " + " OR ".join(", ".join(a) for a in l["alternatives"])
        elif l["kind"] == "shape":
            target = f"shape `{l.get('shape')}`"
        else:
            target = f"MISSING: {l.get('concept')}"
        mark = {"pass": "✓", "fail": "✗", "ignored": "–"}[l["check"]]
        extra = f" ({'; '.join(l['problems'])})" if l.get("problems") and l["check"] == "fail" else ""
        parts.append(f"{mark} \"{_esc(l['phrase'])}\" → {_esc(target)}{_esc(extra)}")
    return "<br>".join(parts) or "-"


def render_correctness_md(report: dict[str, Any]) -> str:
    s = report["summary"]
    lines = ["# Correctness report", "", *_meta_lines(report["meta"]), ""]
    lines += [
        "## Score",
        "",
        f"**{s['score']:.4f}** = {s['formula']} = {s['calculation']}",
        "",
        "| verdict | count |",
        "|---|---|",
        *[f"| {v} | {c} |" for v, c in s["counts"].items()],
        "",
        f"Verdicts whose evidence failed a code check: {s['verdicts_with_evidence_issues']}.",
        "",
        "## Verdicts",
        "",
        "| id | question | verdict | rationale |",
        "|---|---|---|---|",
    ]
    for r in report["results"]:
        flag = " ⚠" if not r["evidence_ok"] else ""
        lines.append(f"| {r['id']} | {_esc(r['text'])} | **{r['verdict']}**{flag} | {_esc(r['rationale'])} |")
    lines += ["", "## Evidence", ""]
    for r in report["results"]:
        lines += [f"### {r['id']}: {r['verdict']}", "", f"> {r['text']}", "", f"Links: {_links_md(r['links'])}", ""]
        if r["readings"]:
            for i, rd in enumerate(r["readings"], 1):
                lines.append(f"- Reading {i}: {_esc(rd['description'])}. Links: {_links_md(rd['links'])}")
            lines.append("")
        for m in r["missing"]:
            lines.append(f"- Missing concept: **{_esc(m['concept'])}**. Closest: {', '.join(m['closest']) or '-'}. {_esc(m.get('why_not') or '')}")
        if r["evidence_issues"]:
            lines.append("- Evidence issues: " + "; ".join(r["evidence_issues"]))
        if r["label_check"]:
            lines.append("- Label check: " + ", ".join(f"{x['dimension']}:{x['item']} {x['status']}" for x in r["label_check"]))
        lines.append("")
    return "\n".join(lines)


def _uncovered_md(dimension: str, uncovered: dict[str, str]) -> str:
    """Uncovered items, columns grouped by table. Reasons other than 'not asked' are shown."""
    if not uncovered:
        return "none"
    def item(name: str, reason: str) -> str:
        short = name.split(".", 1)[1] if dimension == "columns" and "." in name else name
        note = reason[len("not asked (") : -1] if reason.startswith("not asked (") and reason.endswith(")") else reason
        return f"`{short}`" + ("" if reason == "not asked" else f" ({note})")
    if dimension != "columns":
        return ", ".join(item(k, v) for k, v in uncovered.items())
    by_table: dict[str, list[str]] = {}
    for name, reason in uncovered.items():
        by_table.setdefault(name.split(".", 1)[0], []).append(item(name, reason))
    return "; ".join(f"**{t}**: {', '.join(items)}" for t, items in by_table.items())


def render_coverage_md(report: dict[str, Any]) -> str:
    s = report["summary"]
    dims = report["dimensions"]
    lines = ["# Coverage report", "", *_meta_lines(report["meta"]), ""]
    lines += ["## Coverage by dimension", "", "| dimension | covered | eligible | % |", "|---|---|---|---|"]
    for d, v in dims.items():
        lines.append(f"| {d} | {v['covered_count']} | {v['eligible']} | {v['pct']} |")
    lines.append("")
    for d, v in dims.items():
        lines.append(f"- **Uncovered {d} ({len(v['uncovered'])}):** {_uncovered_md(d, v['uncovered'])}")
    lines += ["", "## Budget", "", report["budget_note"], ""]
    lines += ["## Which questions cover each item", ""]
    for d, v in dims.items():
        lines += [f"### {d.capitalize()}", "", "| item | covered by |", "|---|---|"]
        for item, ids in v["covered"].items():
            lines.append(f"| `{item}` | {', '.join(ids)} |")
        lines.append("")
    rep = report["repetition"]
    lines += [
        "## Repetition",
        "",
        f"- Duplicate pairs (same tables, columns and shapes): {', '.join(' = '.join(p) for p in rep['duplicate_pairs']) or 'none'}",
        f"- Questions covering nothing unique: {', '.join(rep['nothing_unique']) or 'none'}",
        f"- Questions earning no credit: {', '.join(rep['no_credit']) or 'none'}",
        "",
        "## Summary score",
        "",
        f"**{s['score']:.2f}** = {s['formula']} = {s['calculation']}",
        "",
        "The three dimensions above, weighted equally. Tables and shapes fill up within a few questions, so at small N "
        "this number mostly tracks column coverage. Read the dimensions first.",
        "",
    ]
    lines += ["## Per question", "", "| id | question | credited | unique | not credited |", "|---|---|---|---|---|"]
    for pq in report["per_question"]:
        cred = "; ".join(f"{d}: {', '.join(v)}" for d, v in pq["credited"].items() if v) or "nothing"
        nc = "; ".join(f"{x.get('phrase') or x.get('item')}: {x['reason']}" for x in pq["not_credited"]) or "-"
        lines.append(f"| {pq['id']} | {_esc(pq['text'])} | {_esc(cred)} | {_esc(', '.join(pq['unique']) or 'nothing')} | {_esc(nc)} |")
    lines += ["", "## Links", ""]
    for pq in report["per_question"]:
        lines.append(f"- **{pq['id']}**: {_links_md(pq['links'])}")
        if pq["label_check"]:
            lines.append("  - Label check: " + ", ".join(f"{x['dimension']}:{x['item']} {x['status']}" for x in pq["label_check"]))
    lines.append("")
    return "\n".join(lines)
